effect.shader:
float rand(vec2 c){ return fract(sin(dot(c,vec2(12.9898,78.233)))*43758.5453); }
void main(){
    vec4 src = texture2DCv(inputImg.texture, acScreenNorm);
    vec3 c = src.a>0.0? src.rgb/src.a : src.rgb;
    float l = dot(c, vec3(0.3,0.59,0.11));
    l = pow(clamp(l,0.0,1.0), 0.7)*gain;
    float n = (rand(acScreenNorm*acScreenSize + fract(acTime))-0.5)*noiseAmt;
    vec3 outc = vec3(0.05, l+n, 0.08) * vec3(0.4,1.0,0.4);
    float d = length(acScreenNorm-0.5);
    outc *= 1.0 - d*d*vignette*2.2;
    gl_FragColor = vec4(clamp(outc,0.0,1.0),1.0)*src.a;
}
